local ServicesTicker = require(script.Parent.Parent.Misc.ServicesTicker)

local HostServicesBootStrap = {}
HostServicesBootStrap.__index = HostServicesBootStrap

function HostServicesBootStrap.new(hostServices: IEnumerable<IHostedService>)
	local self = setmetatable({}, HostServicesBootStrap)
	self._hostServices = hostServices
	self._servicesTicker = ServicesTicker.new(self._hostServices)
	return self
end

function HostServicesBootStrap:Start()
	for _, service in self._hostServices do
		if service.Start then
			service:Start()
		end
	end

	self._servicesTicker:Start()
end

function HostServicesBootStrap:Stop()
	self._servicesTicker:Stop()

	for _, service in self._hostServices do
		if service.Stop then
			service:Stop()
		end
	end
end

function HostServicesBootStrap:Dispose()
	self:Stop()
end

return HostServicesBootStrap
